# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#1e3a8a" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">İSLAMİ İLİMLER, COĞRAFYA, DİL, TARİH VE FELSEFE ÖNCÜLERİ</text>\n  \n  <rect x="15" y="54" width="215" height="192" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="215" height="26" fill="#2563eb" rx="6"/>\n  <text x="122" y="71" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">1. İSLAMİ İLİMLER (TEMEL ESERLER)</text>\n  <text x="24" y="94" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Tefsir İlmi:</text>\n  <text x="28" y="108" fill="#1e293b" font-size="9">Fahreddin Razi (et-Tefsirü\'l-Kebir),</text>\n  <text x="28" y="121" fill="#1e293b" font-size="9">Zemahşeri (Keşşaf), Beydavi (Envarü\'t-Tenzil),</text>\n  <text x="28" y="134" fill="#1e293b" font-size="9">Elmalılı M. Hamdi Yazır (Hak Dini Kur\'an Dili)</text>\n  <text x="24" y="151" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Hadis İlmi (Kütüb-i Sitte):</text>\n  <text x="28" y="165" fill="#1e293b" font-size="9">Buhari, Müslim, Tirmizi, İbni Mace,</text>\n  <text x="28" y="178" fill="#1e293b" font-size="9">Ebu Davud, Nesai</text>\n  <text x="24" y="195" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Kelam ve Fıkıh İlmi:</text>\n  <text x="28" y="209" fill="#1e293b" font-size="9">Ebu Hanife (Fıkh-ı Ekber), İmam Matüridi</text>\n  <text x="28" y="222" fill="#1e293b" font-size="9">(Kitabü\'t-Tevhid), Eş\'ari; İmam Malik,</text>\n  <text x="28" y="235" fill="#1e293b" font-size="9">İmam Şafii, Ahmed bin Hanbel</text>\n\n  <rect x="242" y="54" width="215" height="192" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5" rx="8"/>\n  <rect x="242" y="54" width="215" height="26" fill="#16a34a" rx="6"/>\n  <text x="350" y="71" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">2. COĞRAFYA VE SEYAHATNAME</text>\n  <text x="251" y="94" fill="#14532d" font-size="9.5" font-weight="bold">• Harizmi:</text>\n  <text x="255" y="108" fill="#1e293b" font-size="9">Kitabü Sureti\'l-Arz (Enlem ve boylam)</text>\n  <text x="251" y="124" fill="#14532d" font-size="9.5" font-weight="bold">• İbni Hurdazbih:</text>\n  <text x="255" y="138" fill="#1e293b" font-size="9">Kitabü\'l-Mesalik ve\'l-Memalik</text>\n  <text x="255" y="150" fill="#15803d" font-size="8.5" font-weight="bold">("İslam Coğrafyasının Babası")</text>\n  <text x="251" y="166" fill="#14532d" font-size="9.5" font-weight="bold">• Piri Reis &amp; Seydi Ali Reis:</text>\n  <text x="255" y="180" fill="#1e293b" font-size="9">Kitab-ı Bahriyye (1513 Dünya Haritası);</text>\n  <text x="255" y="193" fill="#1e293b" font-size="9">Mir\'atü\'l-Memalik ve Kitabü\'l-Muhit</text>\n  <text x="251" y="209" fill="#14532d" font-size="9.5" font-weight="bold">• Kâtip Çelebi, Evliya Çelebi, İbni Battuta:</text>\n  <text x="255" y="223" fill="#1e293b" font-size="9">Cihannüma ve meşhur Seyahatname\'ler</text>\n  <text x="255" y="236" fill="#1e293b" font-size="9">Ayrıca: Belhi, Makdisi, Muhammed İdrisi</text>\n\n  <rect x="470" y="54" width="215" height="192" fill="#fefce8" stroke="#eab308" stroke-width="1.5" rx="8"/>\n  <rect x="470" y="54" width="215" height="26" fill="#ca8a04" rx="6"/>\n  <text x="577" y="71" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">3. DİL, TARİH VE FELSEFE</text>\n  <text x="479" y="94" fill="#713f12" font-size="9.5" font-weight="bold">• Dil ve Edebiyat:</text>\n  <text x="483" y="108" fill="#1e293b" font-size="9">Ebü\'l-Esved ed-Düeli (Kur\'an harekeleme),</text>\n  <text x="483" y="121" fill="#1e293b" font-size="9">Halil bin Ahmed (Kitabü\'l-Ayn),</text>\n  <text x="483" y="134" fill="#1e293b" font-size="9">Cahiz (Kitabü\'l-Hayevan - 7 cilt)</text>\n  <text x="479" y="151" fill="#713f12" font-size="9.5" font-weight="bold">• Tarih İlmi:</text>\n  <text x="483" y="165" fill="#1e293b" font-size="9">Taberi (Tarihü\'l-Ümem ve\'l-Müluk),</text>\n  <text x="483" y="178" fill="#1e293b" font-size="9">İbni Haldun (Mukaddime - Sosyoloji),</text>\n  <text x="483" y="191" fill="#1e293b" font-size="9">Ahmet Cevdet Paşa (Kısas-ı Enbiya)</text>\n  <text x="479" y="208" fill="#713f12" font-size="9.5" font-weight="bold">• İslam Felsefesi:</text>\n  <text x="483" y="222" fill="#1e293b" font-size="9">Kindi (İlk İslam filozofu), Farabi (Muallim-i</text>\n  <text x="483" y="235" fill="#1e293b" font-size="9">Sani, el-Medinetü\'l-Fazıla), İbni Sina, İbni Rüşd</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="32" fill="#0f766e" rx="8"/>\n  <text x="350" y="30" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">ASTRONOMİ, MATEMATİK, FİZİK, KİMYA, TIP VE HAVACILIK ÖNCÜLERİ</text>\n\n  <rect x="15" y="50" width="330" height="96" fill="#f0fdfa" stroke="#14b8a6" stroke-width="1.5" rx="8"/>\n  <text x="180" y="68" fill="#0f766e" font-size="10.5" font-weight="bold" text-anchor="middle">ASTRONOMİ VE MATEMATİK</text>\n  <line x1="25" y1="73" x2="335" y2="73" stroke="#14b8a6" stroke-width="1"/>\n  <text x="24" y="88" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Fezari:</tspan> İlk usturlap | <tspan font-weight="bold">Fergani:</tspan> Güneş\'in dönüşü (Alfraganus)</text>\n  <text x="24" y="102" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Bettani:</tspan> Güneş yılı (365g 5s 46dk 24sn) | <tspan font-weight="bold">Biruni:</tspan> Dünya\'nın dönüşü</text>\n  <text x="24" y="116" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Uluğ Bey:</tspan> Semerkant Rasathanesi | <tspan font-weight="bold">Ali Kuşçu:</tspan> Ay\'ın ilk haritası</text>\n  <text x="24" y="130" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Harizmi:</tspan> el-Cebr ve\'l-Mukabele, 0 ve x | <tspan font-weight="bold">Ömer Hayyam:</tspan> Kübik denklem</text>\n  <text x="24" y="142" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Nasirüddin Tusi:</tspan> Tusi Çifti | <tspan font-weight="bold">Gıyaseddin Cemşid Kâşî:</tspan> Ondalık kesir</text>\n\n  <rect x="355" y="50" width="330" height="96" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <text x="520" y="68" fill="#1d4ed8" font-size="10.5" font-weight="bold" text-anchor="middle">FİZİK, KİMYA VE SİBERNETİK</text>\n  <line x1="365" y1="73" x2="675" y2="73" stroke="#3b82f6" stroke-width="1"/>\n  <text x="364" y="88" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Cabir bin Hayyan:</tspan> Modern kimya, imbik, altın suyu, atomun</text>\n  <text x="364" y="101" fill="#1e293b" font-size="9">  parçalanabileceği (<tspan font-style="italic">cüz-ü la yetecezza</tspan>)</text>\n  <text x="364" y="115" fill="#1e293b" font-size="9">• <tspan font-weight="bold">İbnü\'l-Heysem:</tspan> Kitabü\'l-Menazır, karanlık oda ve görme olayı</text>\n  <text x="364" y="129" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Cezeri:</tspan> Sibernetik ve robotik öncüsü, Fil Saati, krank mili</text>\n  <text x="364" y="142" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Aziz Sancar:</tspan> DNA onarımı haritalaması (2015 Nobel Kimya Ödülü)</text>\n\n  <rect x="15" y="154" width="330" height="96" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5" rx="8"/>\n  <text x="180" y="172" fill="#be185d" font-size="10.5" font-weight="bold" text-anchor="middle">TIP VE CERRAHİ BİLİMİ</text>\n  <line x1="25" y1="177" x2="335" y2="177" stroke="#ec4899" stroke-width="1"/>\n  <text x="24" y="192" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Kindi:</tspan> Psikofizyoloji | <tspan font-weight="bold">Sabit bin Kurre:</tspan> İlk anestezi uygulaması</text>\n  <text x="24" y="206" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Ebu Bekir Razi:</tspan> el-Havi, çiçek ve kızamık farkı, gliserin/soda</text>\n  <text x="24" y="220" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Zehravi:</tspan> Kitabü\'t-Tasrif (Cerrahi aletler) | <tspan font-weight="bold">İbni Sina:</tspan> el-Kanun fi\'t-Tıb</text>\n  <text x="24" y="234" fill="#1e293b" font-size="9">• <tspan font-weight="bold">İbnü\'n-Nefis:</tspan> Küçük kan dolaşımı | <tspan font-weight="bold">Akşemseddin:</tspan> Maddetü\'l-Hayat</text>\n  <text x="24" y="245" fill="#be185d" font-size="8.5" font-weight="bold">  (Akşemseddin bulaşıcı hastalıkta mikrobu ilk tanımlayan âlimdir)</text>\n\n  <rect x="355" y="154" width="330" height="96" fill="#fff7ed" stroke="#f97316" stroke-width="1.5" rx="8"/>\n  <text x="520" y="172" fill="#c2410c" font-size="10.5" font-weight="bold" text-anchor="middle">HAVACILIK TARİHİNDE ÖNCÜLER</text>\n  <line x1="365" y1="177" x2="675" y2="177" stroke="#f97316" stroke-width="1"/>\n  <text x="364" y="192" fill="#1e293b" font-size="9">• <tspan font-weight="bold">İbni Firnas (ö. 888):</tspan> Kanatlı cihazla ilk uçuş (Ay\'da krater adı)</text>\n  <text x="364" y="206" fill="#1e293b" font-size="9">• <tspan font-weight="bold">İsmail Cevheri:</tspan> Uçuş çalışmalarıyla Hezarfen\'e ilham kaynağı oldu</text>\n  <text x="364" y="220" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Lagari Hasan Çelebi:</tspan> Barutlu füzeyle ilk dikey roket uçuşu (17. yy)</text>\n  <text x="364" y="234" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Hezarfen Ahmed Çelebi:</tspan> Galata Kulesi\'nden Üsküdar\'a uçuş</text>\n  <text x="364" y="246" fill="#1e293b" font-size="9">• <tspan font-weight="bold">Nuri Demirağ:</tspan> Nu.D.38 uçağı | <tspan font-weight="bold">Vecihi Hürkuş:</tspan> Vecihi K-VI uçağı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#312e81" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">KUR\'AN\'DAN MESAJLAR: FATIR SURESİ 27-28. AYETLER VE HAŞYET BİLİNCİ</text>\n\n  <rect x="15" y="54" width="210" height="125" fill="#eef2ff" stroke="#6366f1" stroke-width="1.5" rx="8"/>\n  <text x="120" y="74" fill="#312e81" font-size="10.5" font-weight="bold" text-anchor="middle">1. KÂİNATTAKİ KEVNÎ AYETLER</text>\n  <line x1="25" y1="80" x2="215" y2="80" stroke="#6366f1" stroke-width="1"/>\n  <text x="25" y="98" fill="#1e293b" font-size="9.5">• Gökten indirilen su (yağmur)</text>\n  <text x="25" y="115" fill="#1e293b" font-size="9.5">• Rengârenk ve çeşit çeşit meyveler</text>\n  <text x="25" y="132" fill="#1e293b" font-size="9.5">• Dağlardaki beyaz, kırmızı ve</text>\n  <text x="25" y="146" fill="#1e293b" font-size="9.5">  simsiyah yollar / kaya tabakaları</text>\n  <text x="25" y="163" fill="#1e293b" font-size="9.5">• İnsanlar, hayvanlar ve davarların</text>\n  <text x="25" y="176" fill="#1e293b" font-size="9.5">  farklı renk ve özelliklerde olması</text>\n\n  <polygon points="230,115 245,107 245,112 255,112 255,118 245,118 245,123" fill="#4f46e5" transform="rotate(180 242.5 115)"/>\n\n  <rect x="260" y="54" width="180" height="125" fill="#f5f3ff" stroke="#8b5cf6" stroke-width="1.5" rx="8"/>\n  <text x="350" y="74" fill="#4c1d95" font-size="10.5" font-weight="bold" text-anchor="middle">2. TEFEKKÜR VE İLİM</text>\n  <line x1="270" y1="80" x2="430" y2="80" stroke="#8b5cf6" stroke-width="1"/>\n  <text x="350" y="102" fill="#1e293b" font-size="9.5" text-anchor="middle">Aynı su ve topraktan</text>\n  <text x="350" y="117" fill="#1e293b" font-size="9.5" text-anchor="middle">farklı renk, tat ve türde</text>\n  <text x="350" y="132" fill="#1e293b" font-size="9.5" text-anchor="middle">varlıkların çıkması,</text>\n  <text x="350" y="147" fill="#4c1d95" font-size="9.5" font-weight="bold" text-anchor="middle">Yüce Allah\'ın sonsuz</text>\n  <text x="350" y="162" fill="#4c1d95" font-size="9.5" font-weight="bold" text-anchor="middle">ilim, irade ve kudretinin</text>\n  <text x="350" y="175" fill="#4c1d95" font-size="9.5" font-weight="bold" text-anchor="middle">açık delilidir.</text>\n\n  <polygon points="445,115 460,107 460,112 470,112 470,118 460,118 460,123" fill="#7c3aed" transform="rotate(180 457.5 115)"/>\n\n  <rect x="475" y="54" width="210" height="125" fill="#fef2f2" stroke="#ef4444" stroke-width="1.5" rx="8"/>\n  <text x="580" y="74" fill="#991b1b" font-size="10.5" font-weight="bold" text-anchor="middle">3. ÂLİMLER VE HAŞYET</text>\n  <line x1="485" y1="80" x2="675" y2="80" stroke="#ef4444" stroke-width="1"/>\n  <text x="580" y="100" fill="#1e293b" font-size="9.5" text-anchor="middle">Kâinattaki bu muazzam</text>\n  <text x="580" y="115" fill="#1e293b" font-size="9.5" text-anchor="middle">düzeni ilimle inceleyen</text>\n  <text x="580" y="130" fill="#991b1b" font-size="10" font-weight="bold" text-anchor="middle">ÂLİMLER (BİLİM İNSANLARI)</text>\n  <text x="580" y="146" fill="#1e293b" font-size="9.5" text-anchor="middle">Allah\'ın yüceliğini kavrar</text>\n  <text x="580" y="161" fill="#1e293b" font-size="9.5" text-anchor="middle">ve O\'na derin saygı</text>\n  <text x="580" y="175" fill="#991b1b" font-size="9.5" font-weight="bold" text-anchor="middle">(HAŞYET) duyarlar.</text>\n\n  <rect x="15" y="190" width="670" height="58" fill="#1e1b4b" rx="8"/>\n  <text x="350" y="212" fill="#fde047" font-size="11.5" font-weight="bold" text-anchor="middle">"Kulları içinden ancak âlimler, Allah\'tan (gereğince) korkar (haşyet duyar).</text>\n  <text x="350" y="232" fill="#ffffff" font-size="11" font-weight="bold" text-anchor="middle">Şüphesiz Allah, daima üstündür (Azîz), çok bağışlayandır (Gafûr)." (Fatır Suresi, 28. Ayet)</text>\n</svg>']

def uygula(v):
    for i, s in enumerate(SVGS):
        if i < len(v.get('bolumler', [])):
            v['bolumler'][i]['gorsel'] = s
